constexpr double PI=3.141592653589793, reloadTime=1.8;
constexpr int W=960,H=600;
const char* world[]={"################","#..............#","#..##....##....#","#..............#","#......#.......#","#..#...#...##..#","#..#...........#","#......##......#","#..............#","#...##....#....#","#.........#....#","#..##..........#","#.......##.....#","#..............#","#..............#","################"};
bool solid(double x,double y){return x<0||y<0||x>=16||y>=16||world[int(y)][int(x)]=='#';}
double wrap(double a){return atan2(sin(a),cos(a));}
enum Sound {Rifle,EnemyShot,MagOut,MagIn,Bolt,Step,Hit,Empty};
struct Bot {double x,y;int hp;double cooldown,flash=0;};
struct Tracer {double x,y,ex,ey,life;bool enemy;};
struct Game {
 double x=2,y=3,a=0,pitch=0,shot=0,muzzle=0,reload=0,time=0,hurt=0,hit=0,recoil=0,steps=0;
 int hp=100,ammo=24,kills=0,round=0;bool won=false;std::vector<Bot> bots;std::vector<Tracer> tracers;std::vector<Sound> sounds;
 Game(){reset();}
 void reset(){x=2;y=3;a=pitch=shot=muzzle=reload=time=hurt=hit=recoil=steps=0;hp=100;ammo=24;kills=0;won=false;round++;bots={{12,3,100,2},{13,8,100,2},{8,13,100,2},{2,12,100,2},{10,6,100,2}};tracers.clear();sounds.clear();}
 double ray(double ox,double oy,double angle,double limit=24) const {for(double d=.02;d<limit;d+=.025)if(solid(ox+cos(angle)*d,oy+sin(angle)*d))return d;return limit;}
 void move(double dx,double dy){double ox=x,oy=y;int n=std::max(1,int(hypot(dx,dy)/.08)+1);for(int i=0;i<n;i++){double nx=x+dx/n,ny=y+dy/n;auto clear=[](double xx,double yy){return !solid(xx-.18,yy-.18)&&!solid(xx+.18,yy-.18)&&!solid(xx-.18,yy+.18)&&!solid(xx+.18,yy+.18);};if(clear(nx,y))x=nx;if(clear(x,ny))y=ny;}steps+=hypot(x-ox,y-oy);if(steps>.95){steps=0;sounds.push_back(Step);}}
 void startReload(){if(hp<=0||won||reload>0||ammo==24)return;reload=reloadTime;sounds.push_back(MagOut);}
 void fire(){if(hp<=0||won||shot>0||reload>0)return;if(ammo<=0){shot=.25;sounds.push_back(Empty);return;}ammo--;shot=.14;muzzle=.055;recoil=1;sounds.push_back(Rifle);Bot* target=nullptr;double nearest=ray(x,y,a);for(auto& b:bots){if(b.hp<=0)continue;double d=hypot(b.x-x,b.y-y),angle=atan2(b.y-y,b.x-x);if(std::abs(wrap(angle-a))<atan2(.28,d)&&std::abs(pitch)<std::max(12.,200/d)&&d<nearest&&ray(x,y,angle)>d-.2){nearest=d;target=&b;}}tracers.push_back({x,y,x+cos(a)*nearest,y+sin(a)*nearest,.09,false});if(target){target->hp-=50;hit=.2;sounds.push_back(Hit);if(target->hp<=0)kills++;}won=kills==int(bots.size());}
 void tick(double dt){time+=dt;muzzle=std::max(0.,muzzle-dt);shot=std::max(0.,shot-dt);hurt=std::max(0.,hurt-dt);hit=std::max(0.,hit-dt);recoil=std::max(0.,recoil-dt*7);for(auto& t:tracers)t.life-=dt;tracers.erase(std::remove_if(tracers.begin(),tracers.end(),[](Tracer t){return t.life<=0;}),tracers.end());if(reload>0){double old=reload;reload=std::max(0.,reload-dt);if(old> .65&&reload<=.65)sounds.push_back(MagIn);if(old>.2&&reload<=.2)sounds.push_back(Bolt);if(reload==0)ammo=24;}if(hp<=0||won)return;for(auto& b:bots){b.flash=std::max(0.,b.flash-dt);if(b.hp<=0)continue;b.cooldown-=dt;double d=hypot(x-b.x,y-b.y),ang=atan2(y-b.y,x-b.x);bool visible=ray(b.x,b.y,ang)>d-.2;if(d>2&&visible){double nx=b.x+cos(ang)*dt*.6,ny=b.y+sin(ang)*dt*.6;if(!solid(nx,ny)){b.x=nx;b.y=ny;}}if(d<10&&visible&&b.cooldown<=0){hp=std::max(0,hp-7);hurt=.3;b.flash=.1;b.cooldown=1.6;tracers.push_back({b.x,b.y,x,y,.14,true});sounds.push_back(EnemyShot);}}}
};
Game game;std::vector<uint32_t> pixels(W*H);std::vector<double> depth(W);bool aiming=false,moving=false;
unsigned rgb(int r,int g,int b){return (std::clamp(r,0,255)<<16)|(std::clamp(g,0,255)<<8)|std::clamp(b,0,255);}
unsigned shade(unsigned c,double v){return rgb(int(((c>>16)&255)*v),int(((c>>8)&255)*v),int((c&255)*v));}
void rect(int x,int y,int w,int h,unsigned c){for(int yy=std::max(0,y);yy<std::min(H,y+h);yy++)for(int xx=std::max(0,x);xx<std::min(W,x+w);xx++)pixels[yy*W+xx]=c;}
void line(int x,int y,int ex,int ey,unsigned c,int width=1){int n=std::max(std::abs(ex-x),std::abs(ey-y));if(n>10000)return;for(int i=0;i<=n;i++){double t=n?double(i)/n:0;rect(int(x+(ex-x)*t),int(y+(ey-y)*t),width,width,c);}}
void ellipse(int cx,int cy,int rx,int ry,unsigned c){for(int y=-ry;y<=ry;y++)for(int x=-rx;x<=rx;x++)if(double(x*x)/(rx*rx)+double(y*y)/(ry*ry)<=1)rect(cx+x,cy+y,1,1,c);}
double fov(){return aiming?.46:.7;}
int horizon(){return H/2+int(game.pitch+game.recoil*9);}
bool project(double x,double y,double height,int& sx,int& sy,double& z){double dx=x-game.x,dy=y-game.y;z=dx*cos(game.a)+dy*sin(game.a);if(z<.08)return false;sx=int(W/2+(-dx*sin(game.a)+dy*cos(game.a))*W/(2*fov()*z));sy=int(horizon()+(0.5-height)*H/z);return sx>-1000&&sx<W+1000;}
void render(){
 int mid=horizon();double ca=cos(game.a),sa=sin(game.a),fv=fov();
 for(int yy=0;yy<H;yy++){double row=yy-mid;for(int xx=0;xx<W;xx++){unsigned c;if(row>0){double d=H*.5/std::max(1.,row),side=(2.*xx/W-1)*fv,wx=game.x+d*(ca-sa*side),wy=game.y+d*(sa+ca*side);int tile=(int(floor(wx*2))+int(floor(wy*2)))&1;double seam=std::min(wx*2-floor(wx*2),wy*2-floor(wy*2));c=shade(seam<.025?0x333B3D:tile?0x72716A:0x65675F,.3+.7/(1+d*.09));}else{double t=double(yy)/H;c=rgb(int(37+t*35),int(54+t*35),int(70+t*30));}pixels[yy*W+xx]=c;}}
 for(int col=0;col<W;col++){double angle=game.a+atan((2.*col/W-1)*fv),raw=game.ray(game.x,game.y,angle),d=raw*cos(angle-game.a);depth[col]=d;int h=std::min(10000,int(H/std::max(.05,d))),top=mid-h/2;double wx=game.x+cos(angle)*raw,wy=game.y+sin(angle)*raw;bool side=std::abs(wx-round(wx))<.04;double u=side?wy:wx;double light=(side?.8:1.)/(1+d*.10);for(int yy=std::max(0,top);yy<std::min(H,top+h);yy++){double v=double(yy-top)/h;int brick=int(v*10);double seam=(u*3+(brick&1)*.5);seam-=floor(seam);bool mortar=fmod(v*10,1.)<.06||seam<.04;unsigned color=mortar?0x42474A:0x9A9585;if(v>.85)color=0x414C51;if(v<.035)color=0xB7B8AE;pixels[yy*W+col]=shade(color,light);}}
 auto bots=game.bots;std::sort(bots.begin(),bots.end(),[](Bot b,Bot c){return hypot(b.x-game.x,b.y-game.y)>hypot(c.x-game.x,c.y-game.y);});
 for(auto b:bots){int cx,base;double z;if(!project(b.x,b.y,0,cx,base,z))continue;int h=std::min(3000,int(H/z));if(b.hp<=0){for(int xx=cx-h/4;xx<cx+h/4;xx++)if(xx>=0&&xx<W&&z<depth[xx])rect(xx,base-h/12,1,h/12,0x343D36);continue;}int top=base-h;for(int xx=std::max(0,cx-h/3);xx<std::min(W,cx+h/3);xx++){if(z>=depth[xx])continue;double u=double(xx-cx)/h;for(int yy=std::max(0,top);yy<std::min(H,base);yy++){double v=double(yy-top)/h;unsigned c=0;bool draw=false;if(v<.17&&std::abs(u)<.105){c=v<.09?0x414B3B:0xB59B78;draw=true;}else if(v>=.17&&v<.61&&std::abs(u)<.20){c=std::abs(u)<.13?0x384439:0x5A6250;if(v>.25&&v<.46&&std::abs(u)<.13)c=0x29332D;draw=true;}else if(v>=.61&&v<.94&&std::abs(u)<.16&&std::abs(u)>.025){c=0x4A5142;draw=true;}else if(v>=.94&&std::abs(u)<.19){c=0x202726;draw=true;}if(v>.36&&v<.41&&u>-.04&&u<.32){c=0x171E22;draw=true;}if(draw)pixels[yy*W+xx]=shade(c,.55+.45/(1+z*.06));}}if(b.flash>0&&cx>=0&&cx<W&&z<depth[cx]){ellipse(cx+h/4,top+h*2/5,std::max(2,h/12),std::max(2,h/18),0xFFE7A1);}}
 for(auto t:game.tracers){int sx,sy,ex,ey;double z1;if(!t.enemy){double d=hypot(t.ex-game.x,t.ey-game.y);ex=W/2;ey=mid+int(H*.04/std::max(1.,d));line(aiming?W/2:W/2+100,H-115,ex,ey,0xFFE5A4,2);ellipse(ex,ey,3,3,0xFFCF75);}else if(project(t.x,t.y,.6,sx,sy,z1)&&sx>=0&&sx<W&&z1<=depth[sx]+.3){line(sx,sy,W/2+75,H-75,0xFFA665,2);}}
 // Weapon, arms, and an animated detachable magazine.
 double phase=game.reload>0?1-game.reload/reloadTime:0;int drop=game.reload>0?int(sin(phase*PI)*110):0;int bob=moving?int(sin(game.time*11)*4):0;int gx=(aiming?W/2:W/2+100)+(moving?int(cos(game.time*5.5)*3):0),gy=H-85-(aiming?60:0)+drop+bob+int(game.recoil*17);
 ellipse(gx-65,gy+95,65,85,0x303E37);ellipse(gx+90,gy+105,70,85,0x303E37);rect(gx-48,gy-20,25,85,0x9B836A);rect(gx+39,gy+4,28,65,0x9B836A);
 rect(gx-24,gy-104,48,142,0x171F24);rect(gx-18,gy-100,36,125,0x3D484F);rect(gx-12,gy-99,8,120,0x606A6E);rect(gx-13,gy-148,26,61,0x252F35);rect(gx-10,gy-151,20,8,0x11191D);rect(gx-18,gy-109,36,10,0x11191D);for(int i=0;i<7;i++)rect(gx-21,gy-80+i*9,42,3,0x1D272E);rect(gx-32,gy+13,64,54,0x202A30);rect(gx-17,gy+18,34,34,0x4C565B);rect(gx-7,gy-155,14,5,0x899795);rect(gx-16,gy-15,32,12,0x10171B);
 int magdrop=game.reload>0?int(sin(phase*PI)*100):0;rect(gx-19-magdrop/3,gy+56+magdrop,38,75,0x343D3F);for(int i=0;i<5;i++)rect(gx-15-magdrop/3,gy+63+magdrop+i*12,29,3,0x202A2C);
 if(game.muzzle>0&&game.reload<=0){ellipse(gx,gy-166,22,12,0xFFB44C);line(gx-35,gy-175,gx+35,gy-155,0xFFE9AF,4);line(gx,gy-190,gx,gy-140,0xFFE9AF,4);}
 // Vignette and damage tint.
 for(int yy=0;yy<H;yy++)for(int xx=0;xx<W;xx++){double dx=(xx-W*.5)/(W*.5),dy=(yy-H*.5)/(H*.5);auto& c=pixels[yy*W+xx];c=shade(c,1-.23*std::min(1.,dx*dx+dy*dy));if(game.hurt>0&& (std::abs(dx)>.9||std::abs(dy)>.87))c=0x8D302B;}
 unsigned cross=game.hit>0?0xF0AE65:0xD8E2DA;int cy=H/2;line(W/2-10,cy,W/2-5,cy,cross);line(W/2+5,cy,W/2+10,cy,cross);line(W/2,cy-10,W/2,cy-5,cross);line(W/2,cy+5,W/2,cy+10,cross);if(game.hit>0){line(W/2-8,cy-8,W/2-3,cy-3,cross);line(W/2+8,cy+8,W/2+3,cy+3,cross);}
 rect(16,16,104,104,0x111B21);for(int yy=0;yy<16;yy++)for(int xx=0;xx<16;xx++)rect(20+xx*6,20+yy*6,5,5,world[yy][xx]=='#'?0x64706C:0x202C30);int mx=20+int(game.x*6),my=20+int(game.y*6);rect(mx-2,my-2,4,4,0x85D7C4);line(mx,my,mx+int(cos(game.a)*8),my+int(sin(game.a)*8),0x85D7C4);
 rect(18,H-58,240,40,0x19252B);rect(W-224,H-58,206,40,0x19252B);rect(28,H-25,120,3,0x394447);rect(28,H-25,game.hp*120/100,3,0x90B9A2);
}
